const response = $input.first().json;
if (response.success !== true) {
  throw new Error('Shopify sync did not report success. Inspect HTTP node output for details.');
}
const failures = response.failed_count ?? response.failure_count ?? 0;
const partial = response.partial_count ?? 0;
if (failures > 0 || partial > 0) {
  throw new Error(`Shopify sync incomplete: ${failures} failed, ${partial} partial. Inspect HTTP node output.`);
}
return [{json: {...response, workflow_checked_at: new Date().toISOString()}}];

const response = $input.first().json;
if (response.success !== true) {
  throw new Error('Gmail sync did not report success. Inspect HTTP node output for details.');
}
const failures = response.failed_count ?? response.failure_count ?? 0;
const partial = response.partial_count ?? 0;
if (failures > 0 || partial > 0) {
  throw new Error(`Gmail sync incomplete: ${failures} failed, ${partial} partial. Inspect HTTP node output.`);
}
return [{json: {...response, workflow_checked_at: new Date().toISOString()}}];

// Extract follow-up summary for reporting
const result = $input.first().json;
const claimed = result.claimed_count || 0;
const completed = result.completed_count || 0;
const escalated = result.escalated_count || 0;
const cancelled = result.cancelled_count || 0;

console.log(`[Order Issue Follow-ups] Processed ${claimed} due jobs (${completed} completed, ${escalated} escalated to owner, ${cancelled} cancelled).`);

