  json: {
    outcome: 'success',
    processed_at: new Date().toISOString(),
    claimed_count: claimed,
    completed_count: completed,
    escalated_count: escalated,
    cancelled_count: cancelled,
    details: result.results || {}
  }
}];

// Format failure alert and prepare audit persistence
const errorPayload = $input.first().json;
console.error('[Order Issue Followup Failure Alert]', JSON.stringify(errorPayload));

const tenantId = errorPayload.tenant_id || errorPayload.target_tenant_id;
if (!tenantId || !tenantId.trim()) {
  throw new Error('Missing required tenant_id in order issue failure payload; fail closed.');
}
const errMsg = errorPayload.error || errorPayload.message || 'Order issue follow-up failed';

return [{
  json: {
    tenant_id: tenantId.trim(),
    event: 'order_issue_followup_failure',
    details: {
      ...errorPayload,
      failed_at: new Date().toISOString(),
      alert_message: errMsg
    },
    error_message: errMsg
  }
}];

// Configuration for Custom Store Sync Orchestration
// - target_tenant_id: Target tenant (fails closed if missing/empty in sandbox mode)
// - target_connection_id: Explicit connection ID, or empty string to enumerate target tenant's active connections
// - page_limit: Page limit (default: 50)
// - max_pages_per_run: Bounded maximum pages per execution (default: 5)
const inputData = $input.first()?.json || {};
const targetTenant = inputData.tenant_id || inputData.target_tenant_id || 'demo-store';

return [
  {
    json: {
      target_tenant_id: targetTenant,
      target_connection_id: inputData.connection_id || inputData.target_connection_id || '',
      page_limit: inputData.page_limit || 50,
      max_pages_per_run: inputData.max_pages_per_run || 5,
      is_sandbox: Boolean(inputData.mock !== undefined ? inputData.mock : true)
    }
  }
];

const config = $('CS Config: Store Connection').first().json;
const response = $input.first().json;

// Missing tenant scope must fail closed
if (!config.target_tenant_id || !config.target_tenant_id.trim()) {
  return [{
    json: {
      is_enumeration_error: true,
      error_message: 'Missing required tenant scope. Missing sandbox scope fails closed.',
      has_connections: false,
      tenant_id: '',
      connections: [],
      connection_index: 0,
      total_connections: 0
    }
  }];
}

// Distinguish HTTP / network / auth failure from zero connections
const isHttpError = Boolean(
  !response ||
  response.error ||
  response.success === false ||
  response.statusCode >= 400 ||
  (typeof response.message === 'string' && response.message.includes('Unauthorized'))
);

if (isHttpError) {
  const errMsg = (typeof response?.error === 'string' ? response.error : response?.error?.message) || response?.message || (response?.error ? JSON.stringify(response.error) : 'Authentication or network error while enumerating connections.');
  return [{
    json: {
      is_enumeration_error: true,
      error_message: errMsg,
      has_connections: false,
      tenant_id: config.target_tenant_id,
      connections: [],
      connection_index: 0,
      total_connections: 0
    }
  }];
}

const connections = Array.isArray(response.connections) ? response.connections : [];
let targets = connections.filter(c => c.is_connected === true);

if (config.target_connection_id && config.target_connection_id.trim()) {
  targets = targets.filter(c => c.connection_id === config.target_connection_id.trim());
}

if (targets.length === 0) {
  return [{
    json: {
      is_enumeration_error: false,
      has_connections: false,
      message: 'No active custom store connections found to synchronize.',
      tenant_id: config.target_tenant_id,
      connections: [],
      connection_index: 0,
      total_connections: 0
    }
  }];
}

return [{
  json: {
    is_enumeration_error: false,
    has_connections: true,
    tenant_id: config.target_tenant_id,
    connections: targets.map(c => ({
      connection_id: c.connection_id,
      tenant_id: c.tenant_id,
      store_name: c.store_name,
      api_base_url: c.api_base_url,
      page_limit: config.page_limit || 50,
      max_pages_per_run: config.max_pages_per_run || 5
    })),
    connection_index: 0,
    total_connections: targets.length,
    overall_results: [],
    overall_has_failures: false
  }
}];

const item = $input.first().json;
if (item.is_enumeration_error) {
  console.error('[Custom Store Sync ENUMERATION FAILED] ' + item.error_message);
  throw new Error('Enumeration failed: ' + item.error_message);
}
console.log('[Custom Store Sync SKIPPED] ' + (item.message || 'No active connections.'));
return [{ json: { status: 'skipped', reason: item.message || 'No active connections' } }];

const state = $input.first().json;
const idx = state.connection_index || 0;
const conn = state.connections[idx];

if (!conn) {
  throw new Error('Connection at index ' + idx + ' is out of bounds');
}

return [{
  json: {
    ...state,
    current_connection: conn,
    tenant_id: conn.tenant_id,
    connection_id: conn.connection_id,
    store_name: conn.store_name,
    page_limit: conn.page_limit,
    max_pages_per_run: conn.max_pages_per_run
  }
}];

const startRes = $input.first().json;
const connState = $('CS Code: Pick Current Connection').first().json;
const conn = connState.current_connection;

const isStartFailed = Boolean(!startRes || startRes.error || startRes.success === false || !startRes.job_id);

if (isStartFailed) {
  const errMsg = (typeof startRes?.error === 'string' ? startRes.error : startRes?.error?.message) || startRes?.message || (startRes?.error ? JSON.stringify(startRes.error) : 'Failed to start sync job (network or API error)');
  return [{
    json: {
      ...connState,
      job_id: startRes?.job_id || ('failed_start_' + conn.connection_id),
      tenant_id: conn.tenant_id,
      connection_id: conn.connection_id,
      store_name: conn.store_name,
      start_failed: true,
      page: 1,
      limit: conn.page_limit || 50,
      max_pages: conn.max_pages_per_run || 5,
      has_next_page: false,
      products_synced: 0,
      orders_synced: 0,
      errors_count: 1,
      error_details: [{
        stage: 'start',
        message: 'Start sync job failed for connection ' + conn.connection_id + ': ' + errMsg,
        timestamp: new Date().toISOString()
      }],
      status: 'failed',
      loop_next: false,
      checkpoint: {},
      products_pages_processed: 0,
      product_checkpoint: {}
    }
  }];
}

const checkpoint = startRes.checkpoint || {};
const resumeProductPage = (checkpoint.products_next_page && typeof checkpoint.products_next_page === 'number')
  ? checkpoint.products_next_page
  : 1;

return [{
  json: {
    ...connState,
    job_id: startRes.job_id,
    tenant_id: startRes.tenant_id || conn.tenant_id,
    connection_id: startRes.connection_id || conn.connection_id,
    store_name: startRes.store_name || conn.store_name,
    start_failed: false,
    page: resumeProductPage,
    limit: conn.page_limit || startRes.page_size || 50,
    max_pages: conn.max_pages_per_run || startRes.max_pages_per_run || 5,
    has_next_page: true,
    products_synced: 0,
    orders_synced: 0,
    errors_count: 0,
    error_details: [],
    status: 'completed',
    loop_next: true,
    checkpoint: checkpoint,
    products_pages_processed: 0,
    product_checkpoint: {}
  }
}];

const state = $input.first().json;
return [{
  json: {
    ...state,
    target_page: state.page || 1
  }
}];

const reqState = $('CS Code: Prepare Products Page Request').first().json;
const response = $input.first().json;

const prevStatus = reqState.status || 'completed';
const prevErrors = Array.isArray(reqState.error_details) ? [...reqState.error_details] : [];
const productsSynced = reqState.products_synced || 0;
const ordersSynced = reqState.orders_synced || 0;
const currentPage = reqState.target_page || reqState.page || 1;

// 1. Detect HTTP / network / 500 / 401 failure
const isHttpFailure = Boolean(!response || response.error || response.success === false || response.statusCode >= 400);

if (isHttpFailure) {
  const errMsg = (typeof response?.error === 'string' ? response.error : response?.error?.message) || response?.message || (response?.error ? JSON.stringify(response.error) : 'HTTP error fetching products page');
  const updatedErrors = [
    ...prevErrors,
    {
      stage: 'products_fetch',
      page: currentPage,
      message: 'HTTP failure on products page ' + currentPage + ': ' + errMsg,
      timestamp: new Date().toISOString()
    }
  ];
  return [{
    json: {
      ...reqState,
      items: [],
      has_next_page: false,
      is_fatal_error: true,
      should_submit_batch: false,
      status: 'partial_failed',
      error_details: updatedErrors,
      errors_count: updatedErrors.length,
      products_synced: productsSynced,
      orders_synced: ordersSynced
    }
  }];
}

// 2. Validate payload data structure
const data = response.data;
if (!data || typeof data !== 'object') {
  const updatedErrors = [
    ...prevErrors,
    {
      stage: 'products_validate',
      page: currentPage,
      message: 'Missing or null data payload in fetch products response for page ' + currentPage,
      timestamp: new Date().toISOString()
    }
  ];
  return [{
    json: {
      ...reqState,
      items: [],
      has_next_page: false,
      is_fatal_error: true,
      should_submit_batch: false,
      status: 'partial_failed',
      error_details: updatedErrors,
      errors_count: updatedErrors.length,
      products_synced: productsSynced,
      orders_synced: ordersSynced
    }
  }];
}

const products = data.products;
if (!Array.isArray(products)) {
  const updatedErrors = [
    ...prevErrors,
    {
      stage: 'products_validate',
      page: currentPage,
      message: 'Malformed response: products field is not an array on page ' + currentPage,
      timestamp: new Date().toISOString()
    }
  ];
  return [{
    json: {
      ...reqState,
      items: [],
      has_next_page: false,
      is_fatal_error: true,
      should_submit_batch: false,
      status: 'partial_failed',
      error_details: updatedErrors,
      errors_count: updatedErrors.length,
      products_synced: productsSynced,
      orders_synced: ordersSynced
    }
  }];
}

// 3. Validate pagination metadata: has_next_page is a REQUIRED boolean!
if (!data.pagination || typeof data.pagination !== 'object' || typeof data.pagination.has_next_page !== 'boolean') {
  const updatedErrors = [
    ...prevErrors,
    {
      stage: 'products_validate',
      page: currentPage,
      message: 'Missing or invalid pagination metadata: pagination.has_next_page must be a boolean on page ' + currentPage,
      timestamp: new Date().toISOString()
    }
  ];
  return [{
    json: {
      ...reqState,
      items: products,
      has_next_page: false,
      is_fatal_error: true,
      should_submit_batch: false,
      status: 'partial_failed',
      error_details: updatedErrors,
      errors_count: updatedErrors.length,
      products_synced: productsSynced,
      orders_synced: ordersSynced
    }
  }];
}

const hasNext = data.pagination.has_next_page;
const currentStatus = (prevStatus === 'failed' || prevStatus === 'partial_failed') ? prevStatus : 'completed';

return [{
  json: {
    ...reqState,
    items: products,
    has_next_page: hasNext,
    is_fatal_error: false,
    should_submit_batch: true,
    status: currentStatus,
    error_details: prevErrors,
    errors_count: prevErrors.length,
    products_synced: productsSynced,
    orders_synced: ordersSynced
  }
}];

const validatedState = $('CS Code: Validate Products Page').first().json;
const batchRes = $input.first().json;

const page = validatedState.target_page || validatedState.page || 1;
const maxPages = validatedState.max_pages || 5;
const hasNextPage = Boolean(validatedState.has_next_page);

let status = validatedState.status || 'completed';
let errorDetails = Array.isArray(validatedState.error_details) ? [...validatedState.error_details] : [];
let productsSynced = validatedState.products_synced || 0;
let productCheckpoint = validatedState.product_checkpoint || {};
let loopNext = false;
let pagesProcessed = validatedState.products_pages_processed || 0;

// Strict API Contract & Batch Validation:
// Accept a batch response ONLY when:
// 1. success === true
// 2. processed_count is a finite, non-negative integer
// 3. no HTTP/API/item failure is present
// Treat {}, missing success, missing processed_count, null, strings, negative numbers and invalid numeric values as malformed failures.
let isBatchValid = false;
let failureReason = '';

if (!validatedState.should_submit_batch) {
  failureReason = 'Batch submission skipped due to previous validation or fetch failure';
} else if (!batchRes || typeof batchRes !== 'object' || Array.isArray(batchRes)) {
  failureReason = 'Malformed batch response: payload is null, primitive, or not an object';
} else if (batchRes.error !== undefined) {
  const errText = (typeof batchRes.error === 'string' ? batchRes.error : batchRes.error?.message) || JSON.stringify(batchRes.error);
  failureReason = 'Batch HTTP/API error: ' + errText;
} else if (typeof batchRes.statusCode === 'number' && batchRes.statusCode >= 400) {
  failureReason = 'Batch HTTP error with status ' + batchRes.statusCode;
} else if (batchRes.success !== true) {
  failureReason = 'Malformed batch response: success must be true (received ' + String(batchRes.success) + ')';
} else if (
  typeof batchRes.processed_count !== 'number' ||
  !Number.isFinite(batchRes.processed_count) ||
  !Number.isInteger(batchRes.processed_count) ||
  batchRes.processed_count < 0
) {
  failureReason = 'Malformed batch response: processed_count must be a finite, non-negative integer (received ' + String(batchRes.processed_count) + ')';
} else if (typeof batchRes.error_count === 'number' && batchRes.error_count > 0) {
  const errMsgs = Array.isArray(batchRes.errors) ? batchRes.errors.map(e => (typeof e === 'object' && e !== null) ? (e.message || JSON.stringify(e)) : String(e)).join('; ') : '';
  failureReason = 'Batch reported item errors (count: ' + batchRes.error_count + '): ' + (errMsgs || 'unspecified item error');
} else if (Array.isArray(batchRes.errors) && batchRes.errors.length > 0) {
  const errMsgs = batchRes.errors.map(e => (typeof e === 'object' && e !== null) ? (e.message || JSON.stringify(e)) : String(e)).join('; ');
  failureReason = 'Batch returned non-empty errors array: ' + errMsgs;
} else if (batchRes.status === 'failed' || batchRes.status === 'partial_failed') {
  failureReason = 'Batch returned degraded status: ' + batchRes.status;
} else {
  isBatchValid = true;
}

if (!isBatchValid) {
  status = (status === 'failed') ? 'failed' : 'partial_failed';
  errorDetails.push({
    stage: 'products_batch',
    page,
    message: 'Batch failure on products page ' + page + ': ' + failureReason,
    timestamp: new Date().toISOString()
  });

  // Preserve the failed page for retry; never advance its checkpoint!
  productCheckpoint = {
    resource: 'products',
    next_page: page,
    last_page_synced: page > 1 ? page - 1 : 0,
    has_outstanding: true,
    timestamp: new Date().toISOString()
  };
  loopNext = false;
} else {
  // Successful and validated batch submission
  productsSynced += batchRes.processed_count;
  pagesProcessed += 1;

  const reachedLimit = pagesProcessed >= maxPages;
  const hasOutstandingData = hasNextPage && reachedLimit;
  const shouldContinue = hasNextPage && !reachedLimit && !validatedState.is_fatal_error;

  if (hasOutstandingData) {
    status = (status === 'failed') ? 'failed' : 'partial_failed';
    productCheckpoint = {
      resource: 'products',
      next_page: page + 1,
      last_page_synced: page,
      has_outstanding: true,
      timestamp: new Date().toISOString()
    };
  } else if (!hasNextPage) {
    productCheckpoint = {
      resource: 'products',
      has_outstanding: false
    };
  }

  loopNext = shouldContinue;
}

const nextTargetPage = (loopNext && !productCheckpoint.has_outstanding) ? page + 1 : page;

return [{
  json: {
    ...validatedState,
    page: nextTargetPage,
    products_synced: productsSynced,
    products_pages_processed: pagesProcessed,
    error_details: errorDetails,
    errors_count: errorDetails.length,
    status,
    loop_next: loopNext,
    product_checkpoint: productCheckpoint,
    has_outstanding_products: Boolean(productCheckpoint?.has_outstanding)
  }
}];

const prev = $input.first().json;
const checkpoint = prev.checkpoint || {};
const resumeOrderPage = (checkpoint.orders_next_page && typeof checkpoint.orders_next_page === 'number')
  ? checkpoint.orders_next_page
  : 1;

return [{
  json: {
    ...prev,
    page: resumeOrderPage,
    has_next_page: true,
    loop_next: true,
    orders_pages_processed: 0,
    order_checkpoint: {},
    has_outstanding_orders: false
  }
}];

const state = $input.first().json;
return [{
  json: {
    ...state,
    target_page: state.page || 1
  }
}];

const reqState = $('CS Code: Prepare Orders Page Request').first().json;
const response = $input.first().json;

const prevStatus = reqState.status || 'completed';
const prevErrors = Array.isArray(reqState.error_details) ? [...reqState.error_details] : [];
const productsSynced = reqState.products_synced || 0;
const ordersSynced = reqState.orders_synced || 0;
const currentPage = reqState.target_page || reqState.page || 1;

// 1. Detect HTTP / network / 500 / 401 failure
const isHttpFailure = Boolean(!response || response.error || response.success === false || response.statusCode >= 400);

if (isHttpFailure) {
  const errMsg = (typeof response?.error === 'string' ? response.error : response?.error?.message) || response?.message || (response?.error ? JSON.stringify(response.error) : 'HTTP error fetching orders page');
  const updatedErrors = [
    ...prevErrors,
    {
      stage: 'orders_fetch',
      page: currentPage,
      message: 'HTTP failure on orders page ' + currentPage + ': ' + errMsg,
      timestamp: new Date().toISOString()
    }
  ];
  return [{
    json: {
      ...reqState,
      items: [],
      has_next_page: false,
      is_fatal_error: true,
      should_submit_batch: false,
      status: 'partial_failed',
      error_details: updatedErrors,
      errors_count: updatedErrors.length,
      products_synced: productsSynced,
      orders_synced: ordersSynced
    }
  }];
}

// 2. Validate payload data structure
const data = response.data;
if (!data || typeof data !== 'object') {
  const updatedErrors = [
    ...prevErrors,
    {
      stage: 'orders_validate',
      page: currentPage,
      message: 'Missing or null data payload in fetch orders response for page ' + currentPage,
      timestamp: new Date().toISOString()
    }
  ];
  return [{
    json: {
      ...reqState,
      items: [],
      has_next_page: false,
      is_fatal_error: true,
      should_submit_batch: false,
      status: 'partial_failed',
      error_details: updatedErrors,
      errors_count: updatedErrors.length,
      products_synced: productsSynced,
      orders_synced: ordersSynced
    }
  }];
}

const orders = data.orders;
if (!Array.isArray(orders)) {
  const updatedErrors = [
    ...prevErrors,
    {
      stage: 'orders_validate',
      page: currentPage,
      message: 'Malformed response: orders field is not an array on page ' + currentPage,
      timestamp: new Date().toISOString()
    }
  ];
  return [{
    json: {
      ...reqState,
      items: [],
      has_next_page: false,
      is_fatal_error: true,
      should_submit_batch: false,
      status: 'partial_failed',
      error_details: updatedErrors,
      errors_count: updatedErrors.length,
      products_synced: productsSynced,
      orders_synced: ordersSynced
    }
  }];
}

// 3. Validate pagination metadata: has_next_page is a REQUIRED boolean!
if (!data.pagination || typeof data.pagination !== 'object' || typeof data.pagination.has_next_page !== 'boolean') {
  const updatedErrors = [
    ...prevErrors,
    {
      stage: 'orders_validate',
      page: currentPage,
      message: 'Missing or invalid pagination metadata: pagination.has_next_page must be a boolean on page ' + currentPage,
      timestamp: new Date().toISOString()
    }
  ];
  return [{
    json: {
      ...reqState,
      items: orders,
      has_next_page: false,
      is_fatal_error: true,
      should_submit_batch: false,
      status: 'partial_failed',
      error_details: updatedErrors,
      errors_count: updatedErrors.length,
      products_synced: productsSynced,
      orders_synced: ordersSynced
    }
  }];
}

const hasNext = data.pagination.has_next_page;
const currentStatus = (prevStatus === 'failed' || prevStatus === 'partial_failed') ? prevStatus : 'completed';

return [{
  json: {
    ...reqState,
    items: orders,
    has_next_page: hasNext,
    is_fatal_error: false,
    should_submit_batch: true,
    status: currentStatus,
    error_details: prevErrors,
    errors_count: prevErrors.length,
    products_synced: productsSynced,
    orders_synced: ordersSynced
  }
}];

const validatedState = $('CS Code: Validate Orders Page').first().json;
const batchRes = $input.first().json;

const page = validatedState.target_page || validatedState.page || 1;
const maxPages = validatedState.max_pages || 5;
const hasNextPage = Boolean(validatedState.has_next_page);

let status = validatedState.status || 'completed';
let errorDetails = Array.isArray(validatedState.error_details) ? [...validatedState.error_details] : [];
let ordersSynced = validatedState.orders_synced || 0;
let orderCheckpoint = validatedState.order_checkpoint || {};
let loopNext = false;
let pagesProcessed = validatedState.orders_pages_processed || 0;

// Strict API Contract & Batch Validation:
// Accept a batch response ONLY when:
// 1. success === true
// 2. processed_count is a finite, non-negative integer
// 3. no HTTP/API/item failure is present
// Treat {}, missing success, missing processed_count, null, strings, negative numbers and invalid numeric values as malformed failures.
let isBatchValid = false;
let failureReason = '';

if (!validatedState.should_submit_batch) {
  failureReason = 'Batch submission skipped due to previous validation or fetch failure';
} else if (!batchRes || typeof batchRes !== 'object' || Array.isArray(batchRes)) {
  failureReason = 'Malformed batch response: payload is null, primitive, or not an object';
} else if (batchRes.error !== undefined) {
  const errText = (typeof batchRes.error === 'string' ? batchRes.error : batchRes.error?.message) || JSON.stringify(batchRes.error);
  failureReason = 'Batch HTTP/API error: ' + errText;
} else if (typeof batchRes.statusCode === 'number' && batchRes.statusCode >= 400) {
  failureReason = 'Batch HTTP error with status ' + batchRes.statusCode;
} else if (batchRes.success !== true) {
  failureReason = 'Malformed batch response: success must be true (received ' + String(batchRes.success) + ')';
} else if (
  typeof batchRes.processed_count !== 'number' ||
  !Number.isFinite(batchRes.processed_count) ||
  !Number.isInteger(batchRes.processed_count) ||
  batchRes.processed_count < 0
) {
  failureReason = 'Malformed batch response: processed_count must be a finite, non-negative integer (received ' + String(batchRes.processed_count) + ')';
} else if (typeof batchRes.error_count === 'number' && batchRes.error_count > 0) {
  const errMsgs = Array.isArray(batchRes.errors) ? batchRes.errors.map(e => (typeof e === 'object' && e !== null) ? (e.message || JSON.stringify(e)) : String(e)).join('; ') : '';
  failureReason = 'Batch reported item errors (count: ' + batchRes.error_count + '): ' + (errMsgs || 'unspecified item error');
} else if (Array.isArray(batchRes.errors) && batchRes.errors.length > 0) {
  const errMsgs = batchRes.errors.map(e => (typeof e === 'object' && e !== null) ? (e.message || JSON.stringify(e)) : String(e)).join('; ');
  failureReason = 'Batch returned non-empty errors array: ' + errMsgs;
} else if (batchRes.status === 'failed' || batchRes.status === 'partial_failed') {
  failureReason = 'Batch returned degraded status: ' + batchRes.status;
} else {
  isBatchValid = true;
}

if (!isBatchValid) {
  status = (status === 'failed') ? 'failed' : 'partial_failed';
  errorDetails.push({
    stage: 'orders_batch',
    page,
    message: 'Batch failure on orders page ' + page + ': ' + failureReason,
    timestamp: new Date().toISOString()
  });

  // Preserve the failed page for retry; never advance its checkpoint!
  orderCheckpoint = {
    resource: 'orders',
    next_page: page,
    last_page_synced: page > 1 ? page - 1 : 0,
    has_outstanding: true,
    timestamp: new Date().toISOString()
  };
  loopNext = false;
} else {
  // Successful and validated batch submission
  ordersSynced += batchRes.processed_count;
  pagesProcessed += 1;

  const reachedLimit = pagesProcessed >= maxPages;
  const hasOutstandingData = hasNextPage && reachedLimit;
  const shouldContinue = hasNextPage && !reachedLimit && !validatedState.is_fatal_error;

  if (hasOutstandingData) {
    status = (status === 'failed') ? 'failed' : 'partial_failed';
    orderCheckpoint = {
      resource: 'orders',
      next_page: page + 1,
      last_page_synced: page,
      has_outstanding: true,
      timestamp: new Date().toISOString()
    };
  } else if (!hasNextPage) {
    orderCheckpoint = {
      resource: 'orders',
      has_outstanding: false
    };
  }

  loopNext = shouldContinue;
}

const nextTargetPage = (loopNext && !orderCheckpoint.has_outstanding) ? page + 1 : page;

return [{
  json: {
    ...validatedState,
    page: nextTargetPage,
    orders_synced: ordersSynced,
    orders_pages_processed: pagesProcessed,
    error_details: errorDetails,
    errors_count: errorDetails.length,
    status,
    loop_next: loopNext,
    order_checkpoint: orderCheckpoint,
    has_outstanding_orders: Boolean(orderCheckpoint?.has_outstanding)
  }
}];

const state = $input.first().json;

let finalStatus = state.status || 'completed';
const errorDetails = Array.isArray(state.error_details) ? [...state.error_details] : [];

const hasOutstandingProducts = Boolean(state.product_checkpoint?.has_outstanding || state.has_outstanding_products);
const hasOutstandingOrders = Boolean(state.order_checkpoint?.has_outstanding || state.has_outstanding_orders);

if (state.errors_count > 0 || errorDetails.length > 0 || hasOutstandingProducts || hasOutstandingOrders) {
  if (finalStatus !== 'failed') {
    finalStatus = 'partial_failed';
  }
}

// Build clean checkpoint: remove stale next_page / outstanding flags from prior syncs
const baseCheckpoint = { ...(state.checkpoint || {}) };
delete baseCheckpoint.products_next_page;
delete baseCheckpoint.products_outstanding;
delete baseCheckpoint.orders_next_page;
delete baseCheckpoint.orders_outstanding;

const checkpoint = {
  ...baseCheckpoint,
  last_synced_at: new Date().toISOString(),
  products_synced: state.products_synced || 0,
  orders_synced: state.orders_synced || 0
};

// Only attach next_page if this run left outstanding data for that resource
if (hasOutstandingProducts && state.product_checkpoint?.next_page) {
  checkpoint.products_next_page = state.product_checkpoint.next_page;
  checkpoint.products_outstanding = true;
}

if (hasOutstandingOrders && state.order_checkpoint?.next_page) {
  checkpoint.orders_next_page = state.order_checkpoint.next_page;
  checkpoint.orders_outstanding = true;
}

const hasOutstandingData = Boolean(hasOutstandingProducts || hasOutstandingOrders);

return [{
  json: {
    ...state,
    job_id: state.job_id,
    tenant_id: state.tenant_id,
    connection_id: state.connection_id,
    status: finalStatus,
    checkpoint: checkpoint,
    summary: {
      products_synced: state.products_synced || 0,
      orders_synced: state.orders_synced || 0,
      pages_synced: (state.page || 1),
      checkpoint: checkpoint,
      has_outstanding_data: hasOutstandingData
    },
    error_details: errorDetails
  }
}];

const finishRes = $input.first().json;
const finishReq = $('CS Code: Prepare Finish Job').first().json;
const connState = $('CS Code: Pick Current Connection').first().json;

const connIdx = finishReq.connection_index ?? connState.connection_index ?? 0;
const totalConns = finishReq.total_connections ?? connState.total_connections ?? (finishReq.connections?.length || 1);

// Detect HTTP errors, response.error, network failure, or malformed Finish responses
const isFinishHttpError = Boolean(!finishRes || finishRes.error || finishRes.statusCode >= 400 || finishRes.success === false);
const hasValidJobPayload = Boolean(finishRes && finishRes.job && typeof finishRes.job === 'object' && typeof finishRes.job.status === 'string');
const isFinishFailed = isFinishHttpError || !hasValidJobPayload;

// Verify persisted backend status before reporting completion
let effectiveStatus = finishReq.status || 'completed';
if (isFinishFailed) {
  effectiveStatus = (effectiveStatus === 'completed') ? 'failed' : effectiveStatus;
} else {
  const persistedStatus = finishRes.job.status;
  if (persistedStatus === 'failed' || persistedStatus === 'partial_failed') {
    effectiveStatus = persistedStatus;
  } else if (effectiveStatus !== 'completed') {
    // Retain failed/partial if the workflow itself registered errors
    effectiveStatus = effectiveStatus;
  } else if (persistedStatus !== 'completed') {
    effectiveStatus = 'failed';
  }
}

const isFailed = (effectiveStatus === 'failed' || effectiveStatus === 'partial_failed' || isFinishFailed);

const connResult = {
  connection_id: finishReq.connection_id,
  store_name: finishReq.store_name,
  job_id: finishReq.job_id,
  status: effectiveStatus,
  products_synced: finishReq.summary?.products_synced || 0,
  orders_synced: finishReq.summary?.orders_synced || 0,
  errors_count: (finishReq.error_details || []).length + (isFinishFailed ? 1 : 0),
  has_outstanding_data: Boolean(finishReq.summary?.has_outstanding_data),
  finish_api_failed: isFinishFailed
};

const updatedResults = [...(finishReq.overall_results || connState.overall_results || []), connResult];
const updatedFailed = Boolean(finishReq.overall_has_failures || connState.overall_has_failures || isFailed);
const nextIdx = connIdx + 1;
const hasMore = nextIdx < totalConns;

return [{
  json: {
    ...finishReq,
    connection_index: nextIdx,
    overall_results: updatedResults,
    overall_has_failures: updatedFailed,
    loop_more_connections: hasMore
  }
}];

const state = $input.first().json;
const results = state.overall_results || [];
const hasFailures = state.overall_has_failures;

console.log('[Custom Store Orchestration COMPLETE] Synced ' + results.length + ' connection(s). Has failures: ' + hasFailures);

if (hasFailures) {
  const failedConns = results.filter(r => r.status === 'failed' || r.status === 'partial_failed');
  const msg = 'Orchestration completed with ' + failedConns.length + ' failed/partial connection(s): ' + failedConns.map(c => c.connection_id + ' [' + c.status + ']').join(', ');
  console.warn(msg);
  throw new Error(msg);
}

return [{
  json: {
    success: true,
    status: 'completed',
    total_connections_synced: results.length,
    results
  }
}];

// Explicit Sandbox Scope & Mock Dispatch Validation
const inputData = $input.first()?.json || {};
const scopeTenant = inputData.sandbox_tenant_id || inputData.tenant_id;

// 1. Missing sandbox scope check:
// Execution fails immediately before any database mutation or claim call
if (!scopeTenant || typeof scopeTenant !== 'string' || !scopeTenant.trim()) {
  throw new Error("Missing explicit sandbox tenant scope: A validated sandbox tenant_id (e.g. 'sandbox-services-alpha') is strictly required before claiming test jobs. Never fall back to claiming all tenants.");
}

const cleanTenant = scopeTenant.trim();

// 2. Unauthorized scope check:
// Only sandbox or test tenants are authorized for sandbox testing
if (!cleanTenant.startsWith('sandbox-') && !cleanTenant.startsWith('test-')) {
  throw new Error(`Unauthorized sandbox scope: '${cleanTenant}' is not an authorized sandbox business workspace. Sandbox tests must target 'sandbox-*' or 'test-*' tenants.`);
}

const isMock = inputData.mock !== undefined ? Boolean(inputData.mock) : true;

return [{
  json: {
    ...inputData,
    sandbox_mode: true,
    tenant_id: cleanTenant,
    mock: isMock,
    claim_limit: inputData.limit || 10
  }
}];

// Log zero jobs found
const result = $input.first().json;
console.log('[Services Follow-up] Zero due follow-up jobs claimed. Polling cycle complete.');
return [{
  json: {
    status: 'idle',
    claimed_count: 0,
    message: 'Zero due follow-up jobs claimed.'
  }
}];

// Prepare normalized inspection parameters
const items = $input.all();
const scopeCfg = $('Validate Sandbox Scope & Mock Config').first()?.json || {};

return items.map(entry => {
  const item = entry.json;
  return {
    json: {
      tenant_id: item.tenant_id,
      lead_id: item.lead_id,
      job_id: item.id,
      attempt_count: item.attempt_count || 0,
      max_attempts: item.max_attempts || 2,
      mock: scopeCfg.mock !== undefined ? scopeCfg.mock : true
    }
  };
});

// Preserve tenant_id, lead_id, job_id and validate business inspection response
const items = $input.all();
const prepItems = $('Prepare Lead Inspection').all();

return items.map((entry, idx) => {
  const inspectRes = entry.json || {};
  const prep = prepItems[idx]?.json || {};

  const tenantId = inspectRes.tenant_id || prep.tenant_id;
  const leadId = inspectRes.lead_id || prep.lead_id;
  const jobId = inspectRes.job_id || prep.job_id;

  let permittedPath = inspectRes.permitted_path || inspectRes.action;
  const isValidPath = permittedPath === 'customer_followup' || permittedPath === 'owner_task_escalation' || permittedPath === 'cancel_obsolete';

  const isHttpError = Boolean(inspectRes.error || inspectRes.statusCode >= 400 || inspectRes.success === false);

  if (isHttpError || !isValidPath) {
    permittedPath = 'unknown_failure';
  }

  return {
    json: {
      ...inspectRes,
      tenant_id: tenantId,
      lead_id: leadId,
      job_id: jobId,
      mock: prep.mock !== undefined ? prep.mock : true,
      permitted_path: permittedPath,
      inspection_valid: isValidPath && !isHttpError
    }
  };
});

